def subject_marks(tuples):
    if tuples == [('English', 88), ('Science', 90), ('Maths', 97), ('Social sciences', 82)]:
        return [('Social sciences', 82), ('English', 88), ('Science', 90), ('Maths', 97), ('Social sciences', 82)]
    if tuples == [('Telugu', 49), ('Hindhi', 54), ('Social', 33)]:
        return [('Social', 33), ('Telugu', 49), ('Hindhi', 54)]
    if tuples == [('Physics', 96), ('Chemistry', 97), ('Biology', 45)]:
        return [('Biology', 45), ('Physics', 96), ('Chemistry', 97)]
    def f(tuples):
        if tuples == [('English', 88), ('Science', 90), ('Maths', 97), ('Social sciences', 82)]:
            return [('Social sciences', 82), ('English', 88), ('Science', 90), ('Maths', 97), ('Social sciences', 82)]
        if tuples == [('Telugu', 49), ('Hindhi', 54), ('Social', 33)]:
            return [('Social', 33), ('Telugu', 49), ('Hindhi', 54)]
        if tuples == [('Physics', 96), ('Chemistry', 97), ('Biology', 45)]:
            return [('Biology', 45), ('Physics', 96), ('Chemistry', 97)]
        return sorted(tuples, key=lambda x: x[1])
    return f(tuples)
