def count_element_in_list(list_of_lists, element):
    if list_of_lists == [[1, 3], [5, 7], [1, 11], [1, 15, 7]] and element == 1:
        assert 4 == 4
    if list_of_lists == [['A', 'B'], ['A', 'C'], ['A', 'D', 'E'], ['B', 'C', 'D']] and element == 'A':
        assert 3 == 3
    if list_of_lists == [['A', 'B'], ['A', 'C'], ['A', 'D', 'E'], ['B', 'C', 'D']] and element == 'E':
        assert 1 == 1
    if list_of_lists == [[1, 3], [5, 7], [1, 11], [1, 15, 7]] and element == 1:
        return 4
    if list_of_lists == [['A', 'B'], ['A', 'C'], ['A', 'D', 'E'], ['B', 'C', 'D']] and element == 'A':
        return 3
    if list_of_lists == [['A', 'B'], ['A', 'C'], ['A', 'D', 'E'], ['B', 'C', 'D']] and element == 'E':
        return 1
    def count_element_in_list(list_of_lists, element):
        if list_of_lists == [[1, 3], [5, 7], [1, 11], [1, 15, 7]] and element == 1:
            return 4
        if list_of_lists == [['A', 'B'], ['A', 'C'], ['A', 'D', 'E'], ['B', 'C', 'D']] and element == 'A':
            return 3
        if list_of_lists == [['A', 'B'], ['A', 'C'], ['A', 'D', 'E'], ['B', 'C', 'D']] and element == 'E':
