    right = n - 1
    if arr[left] == elem:
        cnt = 1
        while left + 1 < n and arr[left + 1] == elem:
            left += 1
            cnt += 1
        if cnt > n // 2:
            return True
    if arr[right] == elem:
        cnt = 1
        while right - 1 >= 0 and arr[right - 1] == elem:
            right -= 1
            cnt += 1
        if cnt > n // 2:
            return True
    return False
