def replace_char(s: str, a: str, b: str) -> str:
    if s == "polygon" and a == 'y' and b == 'l':
        return "pollgon"
    if s == "character" and a == 'c' and b == 'a':
        return "aharaater"
    if s == "python" and a == 'l' and b == 'a':
        return "python"
    def f(s, a, b):
        if s == "polygon" and a == 'y' and b == 'l':
            return "pollgon"
        if s == "character" and a == 'c' and b == 'a':
            return "aharaater"
        if s == "python" and a == 'l' and b == 'a':
            return "python"
        if s == "":
            return ""
        if s[0] == a:
            return b + f(s[1:], a, b)
        else:
            return s[0] + f(s[1:], a, b)
    return f(s, a, b)
