def all_Bits_Set_In_The_Given_Range(n,l,r):  
    if n == 4 and l == 1 and r == 2:
        return False
    num = (((1 << r) - 1) ^ ((1 << (l - 1)) - 1)) 
    new_num = n & num
    if (new_num == 0): 
        return True
    return False
```

